import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"巽下艮上 蠱：","description":"京氏易傳 - 巽下艮上 蠱：","frontmatter":{"title":"巽下艮上 蠱：","description":"京氏易傳 - 巽下艮上 蠱："},"headers":[],"relativePath":"classics/jingshi/049.md","filePath":"classics/jingshi/049.md"}'),i={name:"classics/jingshi/049.md"};function r(c,a,o,p,d,m){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"巽下艮上-蠱",tabindex:"-1"},[l("巽下艮上 蠱： "),e("a",{class:"header-anchor",href:"#巽下艮上-蠱","aria-label":"Permalink to “巽下艮上 蠱：”"},"​")],-1),e("p",null,"適六爻，陰陽上下，本道存也。氣運週而復始。山下見風，止而順；內互悅而動。《易》雲：“蠱者，事也”。（虎易注：“蠱者，事也”。語出序卦傳。）先甲後甲，事分而令行。金土合木象，複本曰歸魂。與震為飛伏。【辛酉金，庚辰土。】九三歸魂立三公在世，應上九見宗廟。",-1),e("p",null,"建始庚戌至乙卯，【寒露，春分。】積算起乙卯至庚寅，（虎易注：庚寅疑為甲寅之誤。）週而復始。土木入艮巽。【土木分艮巽宮。】",-1),e("p",null,"五星從位起太陰，【太陰水星入卦用。】危宿從位降辛酉金，【二十八宿，危宿入巽歸魂山風蠱，九三辛酉金位上。】分氣候二十八。【起積算數二十八，卦宮定吉凶。】",-1),e("p",null,"木上見土，風落山，貞，幹於父事。陰陽復位，長幼分焉。八卦循環，始於巽，歸魂內象見還元。六爻進退，吉凶在於四時。積算起宮，從乎建始。【卦用及身也。】",-1),e("p",null,"升陰陽，巽宮適變入離，文柔分矣。陰入陽退，見中虛，次水中女。（虎易注：“水”字疑為“入”或者“降”字之誤。）八卦相蕩，陰陽定位，遷入離宮八卦，純火，以日用事。",-1)])])}const f=s(i,[["render",r]]);export{_ as __pageData,f as default};
